result = None
selected = value.get('selectedPens') if hasattr(value, 'get') else None
hours = value.get('hours') if hasattr(value, 'get') else 1
if selected is None:
	return result
if isinstance(selected, (str, unicode)):
	selected = [selected] if selected else []
try:
	hours = int(hours) if hours is not None else 1
except:
	hours = 1
if hours <= 0:
	hours = 1

paths = []
aliases = []
seen = set()
for item in selected:
	path = str(item or '').strip()
	if not path or path in seen:
		continue
	seen.add(path)
	paths.append(path)
	leaf = path.rsplit('/', 1)[-1]
	parts = path.split('/')
	if len(parts) >= 2 and leaf.upper() == 'VALUE':
		alias = parts[-2]
	else:
		alias = leaf
	aliases.append(alias)

if not paths:
	return result

end = system.date.now()
start = system.date.addHours(end, -hours)
try:
	result = system.tag.queryTagHistory(
		paths=paths,
		startDate=start,
		endDate=end,
		returnSize=120,
		aggregationMode='Average',
		returnFormat='Wide',
		columnNames=aliases
	)
except:
	result = None
return result

result = []
tag_path = value.get('tagPath', '') if hasattr(value, 'get') else ''
hiddenTagsInput = value.get('hiddenTags', '') if hasattr(value, 'get') else ''
if tag_path:
	tag_path = str(tag_path).rstrip('/')
if not tag_path:
	return result

hidden_set = set()
try:
	text = str(hiddenTagsInput or '')
	if text:
		text = text.replace(';', ',')
		for item in text.split(','):
			item = item.strip()
			if item:
				hidden_set.add(item)
except Exception:
	pass

def isHidden(fullPath):
	if not hidden_set:
		return False
	stripped = fullPath.split(']', 1)[-1] if ']' in fullPath else fullPath
	norm = stripped.replace(chr(92), '/')
	if fullPath in hidden_set or stripped in hidden_set or norm in hidden_set:
		return True
	norm_slash = '/' + norm.strip('/') + '/'
	for h in hidden_set:
		hh = str(h).replace(chr(92), '/')
		if hh.endswith('/'):
			seg = hh.strip('/')
			if not seg:
				continue
			if ('/' + seg + '/') in norm_slash:
				return True
			if norm.strip('/') == seg or norm.strip('/').startswith(seg + '/'):
				return True
		else:
			if norm.endswith('/' + hh) or norm.split('/')[-1] == hh:
				return True
	return False

candidates = []
try:
	browse = system.tag.browse(path=tag_path, filter={'recursive': True}).getResults()
except:
	browse = []
for entry in browse:
	try:
		tag_type = str(entry['tagType'])
	except:
		tag_type = ''
	if tag_type in ('Folder', 'UdtType', 'UdtInstance', 'Property'):
		continue
	full_path = str(entry['fullPath'])
	if '.' in full_path.rsplit('/', 1)[-1]:
		continue
	if isHidden(full_path):
		continue
	candidates.append(full_path)

if not candidates:
	return result

all_paths = []
for p in candidates:
	all_paths.append(p + '.Enabled')
	all_paths.append(p + '.HistoryEnabled')
	all_paths.append(p + '.DataType')
try:
	all_values = system.tag.readBlocking(all_paths)
except:
	return result

for i, full_path in enumerate(candidates):
	enabled_qv = all_values[i * 3]
	he_qv = all_values[i * 3 + 1]
	dt_qv = all_values[i * 3 + 2]
	try:
		if not enabled_qv.value:
			continue
	except:
		continue
	try:
		if not he_qv.value:
			continue
	except:
		continue
	try:
		dt_raw = dt_qv.value if dt_qv is not None else ''
		if hasattr(dt_raw, 'name'):
			dt = str(dt_raw.name).lower()
		else:
			dt = str(dt_raw).lower()
		if '.' in dt:
			dt = dt.rsplit('.', 1)[-1]
	except:
		dt = ''
	if 'string' in dt or 'date' in dt or 'bool' in dt:
		continue
	parts = full_path.split('/')
	leaf_name = parts[-1] if parts else full_path
	if len(parts) >= 2 and leaf_name.upper() == 'VALUE':
		alias = parts[-2]
	else:
		alias = leaf_name
	result.append({'label': alias, 'value': full_path})
return result

selected = value.get('selectedPens') or []
data = value.get('chartData')
series = []
if data is None:
	return series
try:
	row_count = data.getRowCount()
except:
	row_count = 0
if row_count <= 0:
	return series
try:
	col_names = list(data.getColumnNames())
except:
	try:
		col_names = [data.getColumnName(i) for i in range(data.getColumnCount())]
	except:
		return series

def add_series(name, column):
	if column not in col_names or column == 't_stamp':
		return
	try:
		filtered = system.dataset.filterColumns(data, ['t_stamp', column])
	except:
		return
	series.append({'name': name or column, 'data': filtered})

used = set()
if isinstance(selected, (str, unicode)):
	selected = [selected] if selected else []
for item in selected or []:
	path = str(item or '')
	leaf = path.rsplit('/', 1)[-1]
	parts = path.split('/')
	alias = parts[-2] if len(parts) >= 2 and leaf.upper() == 'VALUE' else leaf
	col = None
	if alias and alias in col_names:
		col = alias
	elif path and path in col_names:
		col = path
	else:
		for n in col_names:
			if n == 't_stamp':
				continue
			if n == leaf or n.endswith('/' + leaf) or n == alias or n.endswith('/' + alias):
				col = n
				break
	if col and col not in used:
		add_series(alias or col, col)
		used.add(col)
if not series:
	for column in col_names:
		if column != 't_stamp':
			add_series(column, column)
return series

